package com.library.model.entity;
public class Reader extends BaseEntity { private String readerNo,username,password,realName,phone,email; private Integer maxBorrow,status;
 public String getReaderNo(){return readerNo;} public void setReaderNo(String v){readerNo=v;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getRealName(){return realName;} public void setRealName(String v){realName=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public Integer getMaxBorrow(){return maxBorrow;} public void setMaxBorrow(Integer v){maxBorrow=v;} public Integer getStatus(){return status;} public void setStatus(Integer v){status=v;} }
